static char **wordsByLen[128];
static int countByLen[128];
static char *rows[128];
static int rowCount;
static char **best;
static int bestCount;
static int bestArea;
static int targetW, targetH;

static bool prefixOk(void) {
  for (int c = 0; c < targetW; c++) {
    char prefix[256];
    for (int r = 0; r < rowCount; r++) prefix[r] = rows[r][c];
    prefix[rowCount] = '\0';
    bool ok = false;
    for (int i = 0; i < countByLen[targetH]; i++) {
      if (strncmp(wordsByLen[targetH][i], prefix, rowCount) == 0) {
        ok = true;
        break;
      }
    }
    if (!ok) return false;
  }
  return true;
}

static void backtrack(void) {
  if (rowCount == targetH) {
    for (int c = 0; c < targetW; c++) {
      char col[256];
      for (int r = 0; r < targetH; r++) col[r] = rows[r][c];
      col[targetH] = '\0';
      bool ok = false;
      for (int i = 0; i < countByLen[targetH]; i++) {
        if (strcmp(wordsByLen[targetH][i], col) == 0) {
          ok = true;
          break;
        }
      }
      if (!ok) return;
    }
    if (targetW * targetH > bestArea) {
      bestArea = targetW * targetH;
      bestCount = targetH;
      for (int i = 0; i < targetH; i++) best[i] = rows[i];
    }
    return;
  }
  for (int i = 0; i < countByLen[targetW]; i++) {
    rows[rowCount++] = wordsByLen[targetW][i];
    if (prefixOk()) backtrack();
    rowCount--;
  }
}

char **maxRectangle(char **words, int wordsSize, int *returnSize) {
  for (int i = 0; i < 128; i++) countByLen[i] = 0;
  for (int i = 0; i < wordsSize; i++) {
    int l = strlen(words[i]);
    wordsByLen[l] = (char **)realloc(wordsByLen[l], sizeof(char *) * (countByLen[l] + 1));
    wordsByLen[l][countByLen[l]++] = words[i];
  }
  best = (char **)malloc(sizeof(char *) * 128);
  bestArea = 0;
  bestCount = 0;
  for (int w = 1; w < 128; w++) {
    for (int h = 1; h < 128; h++) {
      if (countByLen[w] == 0 || countByLen[h] == 0) continue;
      if (w * h <= bestArea) continue;
      targetW = w;
      targetH = h;
      rowCount = 0;
      backtrack();
    }
  }
  *returnSize = bestCount;
  return best;
}

class Solution {
  unordered_map<int, vector<string>> byLen;
  vector<string> rows;
  vector<string> best;
  int bestArea = 0;
  int targetW = 0, targetH = 0;

  bool prefixOk() {
    for (int c = 0; c < targetW; c++) {
      string prefix;
      for (int r = 0; r < (int)rows.size(); r++) prefix += rows[r][c];
      bool ok = false;
      for (const string &w : byLen[targetH]) {
        if (w.compare(0, prefix.size(), prefix) == 0) {
          ok = true;
          break;
        }
      }
      if (!ok) return false;
    }
    return true;
  }

  void backtrack() {
    if ((int)rows.size() == targetH) {
      for (int c = 0; c < targetW; c++) {
        string col;
        for (int r = 0; r < targetH; r++) col += rows[r][c];
        if (!count(byLen[targetH].begin(), byLen[targetH].end(), col)) return;
      }
      if (targetW * targetH > bestArea) {
        bestArea = targetW * targetH;
        best = rows;
      }
      return;
    }
    for (const string &w : byLen[targetW]) {
      rows.push_back(w);
      if (prefixOk()) backtrack();
      rows.pop_back();
    }
  }

public:
  vector<string> maxRectangle(vector<string> &words) {
    for (const string &w : words) byLen[w.size()].push_back(w);
    for (auto &a : byLen) {
      for (auto &b : byLen) {
        int w = a.first, h = b.first;
        if (w * h <= bestArea) continue;
        targetW = w;
        targetH = h;
        rows.clear();
        backtrack();
      }
    }
    return best;
  }
};

var byLen map[int][]string
var rows []string
var best []string
var bestArea, targetW, targetH int

func prefixOk() bool {
	for c := 0; c < targetW; c++ {
		var sb strings.Builder
		for r := 0; r < len(rows); r++ {
			sb.WriteByte(rows[r][c])
		}
		prefix := sb.String()
		ok := false
		for _, w := range byLen[targetH] {
			if strings.HasPrefix(w, prefix) {
				ok = true
				break
			}
		}
		if !ok {
			return false
		}
	}
	return true
}

func backtrack() {
	if len(rows) == targetH {
		for c := 0; c < targetW; c++ {
			var sb strings.Builder
			for r := 0; r < targetH; r++ {
				sb.WriteByte(rows[r][c])
			}
			col := sb.String()
			found := false
			for _, w := range byLen[targetH] {
				if w == col {
					found = true
					break
				}
			}
			if !found {
				return
			}
		}
		if targetW*targetH > bestArea {
			bestArea = targetW * targetH
			best = append([]string{}, rows...)
		}
		return
	}
	for _, w := range byLen[targetW] {
		rows = append(rows, w)
		if prefixOk() {
			backtrack()
		}
		rows = rows[:len(rows)-1]
	}
}

func maxRectangle(words []string) []string {
	byLen = map[int][]string{}
	for _, w := range words {
		byLen[len(w)] = append(byLen[len(w)], w)
	}
	bestArea = 0
	best = nil
	for w := range byLen {
		for h := range byLen {
			if w*h <= bestArea {
				continue
			}
			targetW, targetH = w, h
			rows = nil
			backtrack()
		}
	}
	return best
}

class Solution {
  private Map<Integer, List<String>> byLen = new HashMap<>();
  private List<String> rows = new ArrayList<>();
  private List<String> best = new ArrayList<>();
  private int bestArea = 0;
  private int targetW = 0, targetH = 0;

  private boolean prefixOk() {
    for (int c = 0; c < targetW; c++) {
      StringBuilder sb = new StringBuilder();
      for (String row : rows) sb.append(row.charAt(c));
      String prefix = sb.toString();
      boolean ok = false;
      for (String w : byLen.get(targetH)) {
        if (w.startsWith(prefix)) {
          ok = true;
          break;
        }
      }
      if (!ok) return false;
    }
    return true;
  }

  private void backtrack() {
    if (rows.size() == targetH) {
      for (int c = 0; c < targetW; c++) {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < targetH; r++) sb.append(rows.get(r).charAt(c));
        if (!byLen.get(targetH).contains(sb.toString())) return;
      }
      if (targetW * targetH > bestArea) {
        bestArea = targetW * targetH;
        best = new ArrayList<>(rows);
      }
      return;
    }
    for (String w : byLen.get(targetW)) {
      rows.add(w);
      if (prefixOk()) backtrack();
      rows.remove(rows.size() - 1);
    }
  }

  public String[] maxRectangle(String[] words) {
    for (String w : words) byLen.computeIfAbsent(w.length(), k -> new ArrayList<>()).add(w);
    for (int w : byLen.keySet()) {
      for (int h : byLen.keySet()) {
        if (w * h <= bestArea) continue;
        targetW = w;
        targetH = h;
        rows.clear();
        backtrack();
      }
    }
    return best.toArray(new String[0]);
  }
}

class Solution:
    def maxRectangle(self, words: List[str]) -> List[str]:
        by_len = {}
        for w in words:
            by_len.setdefault(len(w), []).append(w)

        best_area = 0
        best = []
        for w in by_len:
            for h in by_len:
                if w * h <= best_area:
                    continue
                rows = []
                col_words = by_len[h]
                col_set = set(col_words)

                def backtrack():
                    nonlocal best_area, best
                    if len(rows) == h:
                        for c in range(w):
                            col = "".join(r[c] for r in rows)
                            if col not in col_set:
                                return
                        best_area = w * h
                        best = rows[:]
                        return
                    for word in by_len[w]:
                        rows.append(word)
                        ok = True
                        for c in range(w):
                            prefix = "".join(r[c] for r in rows)
                            if not any(cw.startswith(prefix) for cw in col_words):
                                ok = False
                                break
                        if ok:
                            backtrack()
                        rows.pop()

                backtrack()
        return best

impl Solution {
  pub fn max_rectangle(words: Vec<String>) -> Vec<String> {
    let mut by_len: HashMap<usize, Vec<String>> = HashMap::new();
    for w in &words {
      by_len.entry(w.len()).or_insert_with(Vec::new).push(w.clone());
    }
    let lengths: Vec<usize> = by_len.keys().cloned().collect();
    let mut best_area = 0;
    let mut best: Vec<String> = vec![];
    for &w in &lengths {
      for &h in &lengths {
        if w * h <= best_area {
          continue;
        }
        let col_words = by_len.get(&h).unwrap().clone();
        let mut rows: Vec<String> = vec![];
        fn backtrack(
          w: usize,
          h: usize,
          by_w: &Vec<String>,
          col_words: &Vec<String>,
          rows: &mut Vec<String>,
          best_area: &mut usize,
          best: &mut Vec<String>,
        ) {
          if rows.len() == h {
            for c in 0..w {
              let col: String = rows.iter().map(|r| r.as_bytes()[c] as char).collect();
              if !col_words.contains(&col) {
                return;
              }
            }
            *best_area = w * h;
            *best = rows.clone();
            return;
          }
          for word in by_w {
            rows.push(word.clone());
            let mut ok = true;
            for c in 0..w {
              let prefix: String = rows.iter().map(|r| r.as_bytes()[c] as char).collect();
              if !col_words.iter().any(|cw| cw.starts_with(&prefix)) {
                ok = false;
                break;
              }
            }
            if ok {
              backtrack(w, h, by_w, col_words, rows, best_area, best);
            }
            rows.pop();
          }
        }
        let by_w = by_len.get(&w).unwrap().clone();
        backtrack(w, h, &by_w, &col_words, &mut rows, &mut best_area, &mut best);
      }
    }
    best
  }
}

const maxRectangle = (words: string[]): string[] => {
  const byLen = new Map<number, string[]>();
  for (const w of words) {
    if (!byLen.has(w.length)) byLen.set(w.length, []);
    byLen.get(w.length)!.push(w);
  }
  let bestArea = 0;
  let best: string[] = [];
  for (const w of byLen.keys()) {
    for (const h of byLen.keys()) {
      if (w * h <= bestArea) continue;
      const rows: string[] = [];
      const colWords = byLen.get(h)!;
      const colSet = new Set(colWords);

      const backtrack = () => {
        if (rows.length === h) {
          for (let c = 0; c < w; c++) {
            const col = rows.map((r) => r[c]).join('');
            if (!colSet.has(col)) return;
          }
          bestArea = w * h;
          best = [...rows];
          return;
        }
        for (const word of byLen.get(w)!) {
          rows.push(word);
          let ok = true;
          for (let c = 0; c < w; c++) {
            const prefix = rows.map((r) => r[c]).join('');
            if (!colWords.some((cw) => cw.startsWith(prefix))) {
              ok = false;
              break;
            }
          }
          if (ok) backtrack();
          rows.pop();
        }
      };

      backtrack();
    }
  }
  return best;
};
